-- Large demo dataset covering 30 bridges and all six bridge types.


UPDATE tb_bridge SET administrative_code='500100',pile_number='K18+650',function_type='公路桥',design_load='公路-I级',built_year=2012,design_unit='交通规划设计院',construction_unit='路桥建设集团',supervision_unit='交通工程监理公司',owner_unit='省交通投资集团',lane_width=20.50,sidewalk_width=2.00,barrier_height=1.20,median_width=0.50,standard_clearance='5.0m',actual_clearance='4.9m',span_combination='6×60m',structural_system='预应力混凝土连续梁',archive_form='电子档案',archive_date='2012-12-20',bridge_engineer='张工程师',card_filler='李检查员',card_date='2026-01-15' WHERE bridge_code='G75-001';

SELECT b.bridge_code,a.archive_item_code,IF(MOD(CRC32(CONCAT(b.bridge_code,a.archive_item_code)),5)=0,'不全','全'),'批量演示档案数据' FROM tb_bridge b CROSS JOIN tb_archive_item a;

SELECT b.bridge_code,c.config_id,c.part_code,c.component_code,CONCAT('DEMO-',LPAD(c.display_order,2,'0')),CONCAT(p.part_name,'第',c.display_order,'项'),'混凝土/钢材','按设计图纸',1,0,1,'由桥型标准矩阵批量生成'
FROM tb_bridge b JOIN tb_bridge_type_component_config c ON c.bridge_type_code=b.bridge_type_code JOIN tb_part p ON p.part_code=c.part_code;

SELECT CONCAT('QI-',REPLACE(b.bridge_code,'-','')),b.bridge_code,DATE_ADD('2025-01-01',INTERVAL MOD(CRC32(b.bridge_code),300) DAY),'省桥梁检测中心','李检查员、陈检查员','张工程师','晴，18℃',bt.bridge_type_name,b.bridge_length/5,b.span_combination,b.structural_system,'常规施工工艺','无重大返工','无','档案齐全','定期观测主要承重构件',CASE MOD(CRC32(b.bridge_code),4) WHEN 0 THEN 'draft' WHEN 1 THEN 'pending' ELSE 'archived' END,2
FROM tb_bridge b JOIN tb_bridge_type bt ON bt.bridge_type_code=b.bridge_type_code;

SELECT i.initial_inspection_code,c.item_code,1,IF(c.requirement_type='required','必检项目已完成','条件项目已核验'),CONCAT('测值-',c.display_order),'符合规范要求'
FROM tb_initial_inspection i JOIN tb_bridge b ON b.bridge_code=i.bridge_code JOIN tb_bridge_type_initial_item_config c ON c.bridge_type_code=b.bridge_type_code;

SELECT CONCAT('QP-',REPLACE(b.bridge_code,'-',''),'-',n.seq),b.bridge_code,DATE_ADD(CONCAT(2024+n.seq,'-01-01'),INTERVAL MOD(CRC32(b.bridge_code),300) DAY),DATE_SUB(DATE_ADD(CONCAT(2024+n.seq,'-01-01'),INTERVAL MOD(CRC32(b.bridge_code),300) DAY),INTERVAL 1 YEAR),NULL,'多云，22℃',1+MOD(CRC32(CONCAT(b.bridge_code,n.seq)),5),'良好','仅记录检查建议',DATE_ADD(DATE_ADD(CONCAT(2024+n.seq,'-01-01'),INTERVAL MOD(CRC32(b.bridge_code),300) DAY),INTERVAL 1 YEAR),'李检查员','王审核员',CASE MOD(CRC32(CONCAT(b.bridge_code,n.seq)),4) WHEN 0 THEN 'draft' WHEN 1 THEN 'pending' ELSE 'archived' END,3
FROM tb_bridge b CROSS JOIN (SELECT 1 seq UNION ALL SELECT 2) n;

SELECT p.periodic_inspection_code,s.bridge_component_id,s.part_code,s.component_code,CASE MOD(CRC32(CONCAT(p.periodic_inspection_code,s.component_code)),5) WHEN 0 THEN '裂缝' WHEN 1 THEN '渗水' WHEN 2 THEN '锈蚀' ELSE '未见明显缺损' END,s.location_desc,'局部',CASE MOD(CRC32(CONCAT(p.periodic_inspection_code,s.component_code)),4) WHEN 0 THEN 'slight' WHEN 1 THEN 'medium' WHEN 2 THEN 'serious' ELSE NULL END,IF(MOD(s.bridge_component_id,11)=0,s.component_serial,NULL),70+MOD(CRC32(CONCAT(p.periodic_inspection_code,s.component_code)),31),'持续观察，必要时安排专项检测',IF(MOD(s.bridge_component_id,17)=0,1,0)
FROM tb_periodic_inspection p JOIN tb_bridge_specific_component s ON s.bridge_code=p.bridge_code;

SELECT p.bridge_code,NULL,c.component_inspection_id,c.part_code,c.defect_type,'表观缺损',c.defect_range,'1处',COALESCE(c.defect_degree_code,'slight'),CONCAT('演示病害：',c.defect_type)
FROM tb_component_inspection c JOIN tb_periodic_inspection p ON p.periodic_inspection_code=c.periodic_inspection_code WHERE c.defect_type<>'未见明显缺损' AND MOD(c.component_inspection_id,5)=0;

SELECT CONCAT('TASK-',i.initial_inspection_code),i.bridge_code,'initial','Ⅰ',i.inspection_date,DATE_ADD(i.inspection_date,INTERVAL 7 DAY),i.inspection_date,DATE_ADD(i.inspection_date,INTERVAL 2 DAY),CASE MOD(CRC32(i.bridge_code),4) WHEN 0 THEN '待分配' WHEN 1 THEN '进行中' WHEN 2 THEN '已完成' ELSE '已审核' END,'初始检查演示任务',2,4 FROM tb_initial_inspection i;

SELECT CONCAT('TASK-',p.periodic_inspection_code),p.bridge_code,'periodic','Ⅱ',p.inspection_date,DATE_ADD(p.inspection_date,INTERVAL 10 DAY),p.inspection_date,DATE_ADD(p.inspection_date,INTERVAL 3 DAY),CASE MOD(CRC32(p.periodic_inspection_code),4) WHEN 0 THEN '待分配' WHEN 1 THEN '进行中' WHEN 2 THEN '已完成' ELSE '已审核' END,'定期检查演示任务',2,4 FROM tb_periodic_inspection p;

SELECT CONCAT('ASG-',REPLACE(t.task_id,'TASK-','')),t.task_id,3,IF(t.task_status IN ('已完成','已审核'),'已完成','待接受') FROM tb_inspection_task t;

SELECT CONCAT('HIS-',REPLACE(t.task_id,'TASK-','')),t.task_id,NULL,t.task_status,2,'演示任务状态' FROM tb_inspection_task t;

SELECT CONCAT('REP-',REPLACE(t.task_id,'TASK-','')),t.task_id,CASE WHEN t.inspection_type='initial' THEN REPLACE(t.task_id,'TASK-','') END,CASE WHEN t.inspection_type='periodic' THEN REPLACE(t.task_id,'TASK-','') END,CONCAT(t.inspection_type,'_record'),'V1.0','HTML',NULL,'已归档',2,4,'批量生成演示报告' FROM tb_inspection_task t WHERE t.task_status='已审核';

SELECT p.bridge_code,p.inspection_date,'periodic',CONCAT(p.rating_level_code,'类'),'未发现影响结构安全的突发病害','持续检查和跟踪观测',p.next_inspection_date FROM tb_periodic_inspection p;
